//! Focused production screenshots for the user's shadow and material/layout regressions.
use std::path::Path;use serde_json::json;use crate::{model::{Model,Page,Action},draw::Text,gpu::Gpu,views::{self,ViewState}};
pub fn run(m:&mut Model,text:&mut Text,gpu:&mut Gpu,out:&Path)->Result<Vec<String>,String>{
 let saved=(m.page,m.mode,m.scroll,m.prefs.clone(),m.native_state.clone(),m.island_tab);let mut captures=vec![];m.page=Page::Focus;m.mode=3;m.scroll=0.;
 for dark in [false,true]{m.prefs.dark=dark;for(w,h)in[(900.,680.),(1706.,1067.)]{let base=views::render(m,text,w,h,&ViewState::default());let label=base.hits.iter().position(|hit|matches!(&hit.action,Action::WorkflowStageEdit(0))).ok_or("workflow stage label missing")?;let r=base.hits[label].rect;let step=base.hits.iter().find(|hit|matches!(&hit.action,Action::WorkflowStageNudge(0,_))).ok_or("workflow stepper missing")?.rect;if r.x1>step.x0-7.{return Err("workflow editable label overlaps the time stepper".into())}
  for pressed in [false,true]{let mut layers=vec![0.;base.hits.len()];layers[label]=0.16;let view=views::render(m,text,w,h,&ViewState{pointer:(r.center().x,r.center().y),pressed:if pressed{Some(label)}else{None},state_layers:layers,..Default::default()});let name=format!("workflow-clean-label-{dark}-{}-{pressed}.png",w as u32);gpu.capture(&view.scene,w as u32,h as u32,&out.join(&name))?;captures.push(name);}
 }}
 m.page=Page::Island;m.island_tab=1;m.scroll=0.;let first=views::render(m,text,900.,680.,&ViewState::default());let mut found=0;for y in(0..=(first.max_scroll as usize+100)).step_by(40){m.scroll=(y as f64).min(first.max_scroll);let v=views::render(m,text,900.,680.,&ViewState::default());for hit in &v.hits{if let Action::NativeEdit(key,value)=&hit.action{if ["ClassicCapsuleMaterial","IslandMaterial","MiniMaterial"].contains(key){if value=="Classic"{return Err("retired Classic material is still exposed".into())}if value=="Glass"||value=="Acrylic"{found+=1;}}}}}if found<6{return Err("two material choices are not reachable for all three surfaces".into())}
 m.scroll=first.max_scroll*0.5;let v=views::render(m,text,900.,680.,&ViewState::default());let name="materials-two-options-900.png";gpu.capture(&v.scene,900,680,&out.join(name))?;captures.push(name.into());
 m.island_tab=0;m.scroll=0.;let first=views::render(m,text,900.,680.,&ViewState::default());let mut modes=std::collections::HashSet::new();for y in(0..=(first.max_scroll as usize+100)).step_by(40){m.scroll=(y as f64).min(first.max_scroll);let v=views::render(m,text,900.,680.,&ViewState::default());for hit in &v.hits{if let Action::NativeEdit("MusicExpandedLayout",value)=&hit.action{if value=="LyricRight"{return Err("retired right-cover choice still exposed".into())}modes.insert(value.to_string());}}}if modes.len()!=3{return Err("music layout must expose exactly three options".into())}
 m.native_state["settings"]["Motion"]["Scheme"]=json!("Expressive");m.page=saved.0;m.mode=saved.1;m.scroll=saved.2;m.prefs=saved.3;m.native_state=saved.4;m.island_tab=saved.5;Ok(captures)
}
